**button.css — Button styling per layout**

[button.css#L15-L138](file:///Users/dwahl/Scripts/pantoken/renderers/pendo/src/css/button.css#L15-L138):
```css
:is(:scope, [class*="instui"]) {
  ._pendo-button {
    height: var(--instui-component-base-button-small-height);
    /* ...base button styles... */
  }

  /* Primary/Custom button variant */
  ._pendo-button-primaryButton,
  ._pendo-button-custom {
    background: var(--instui-color-background-interactive-action-primary-base);
    /* ...primary button styles... */
  }

  /* Secondary button variant */
  ._pendo-button-secondaryButton {
    background: var(--instui-component-base-button-secondary-background);
    /* ...secondary button styles... */
  }

  /* Tertiary button variant */
  ._pendo-button-tertiaryButton {
    background: transparent;
    /* ...tertiary button styles... */
  }

  /* Surveys: Submit / Finish buttons */
  &._pendo-guide-walkthrough_:not([data-layout="tooltipBlank"], [data-layout="lightboxBlank"]) {
    /* Submit / Finish buttons: Center only if they're the only button in the container */
    div:has(> ._pendo-button-primaryButton):not(:has(> :not(._pendo-button-primaryButton))) {
      display: flex;
      justify-content: center;
    }
  }
}

/* Banner buttons use the on-colour treatment from the InstUI banner component. */
:is(:scope, [class*="instui"])[data-layout="lightboxBlank"]:not([class*="instui-alert"]) {
  :is(._pendo-button-primaryButton, ._pendo-button-custom) {
    background: var(--instui-component-base-button-primary-inverse-background);
    border-color: var(--instui-component-base-button-primary-inverse-border-color);
    color: var(--instui-component-base-button-primary-inverse-color);
    /* ...inverse button colors on hover/active/disabled... */
  }

  :is(._pendo-button-secondaryButton, ._pendo-button-tertiaryButton) {
    background: transparent;
    border-color: var(--instui-component-base-button-primary-inverse-ghost-border-color);
    color: light-dark(
      var(--instui-component-base-button-primary-inverse-color),
      var(--instui-component-base-button-primary-inverse-ghost-border-color)
    );
    /* ...ghost button variant states... */
  }
}
```

