{"filePath": "/tmp/pendo-check/index.html", "content": "<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>pendo banner survey check</title>
    <link rel="stylesheet" href="./global.css" />
    <style>
      body {
        margin: 0;
        min-height: 300vh;
        background: #f5f5f5;
        font-family: system-ui, sans-serif;
      }
      .note {
        padding: 1rem;
        font: 600 14px/1.4 system-ui;
      }
    </style>
  </head>
  <body>
    <p class="note">
      PMF survey is fixed bottom-right (450px). NPS bar is fixed bottom, full width. Scroll/resize to
      exercise the container query.
    </p>

    <!-- ── PMF (Feature Survey): no data-layout ── -->
    <div
      id="pendo-base"
      class="instui-banner-poll _pendo-step-container _pendo-guide-walkthrough_"
      style="visibility: visible"
    >
      <div
        id="pendo-g-pmf"
        class="_pendo-step-container-size"
        data-vertical-alignment="Bottom Right Aligned"
        style="
          display: block;
          width: 450px;
          z-index: 300000;
          pointer-events: all;
          position: fixed;
          bottom: 20px;
          right: 20px;
          visibility: visible;
          height: 483px;
        "
      >
        <div
          id="pendo-guide-container-pmf"
          role="complementary"
          class="_pendo-step-container-styles"
          style="
            display: block;
            border-radius: 0px;
            border: 1px solid rgb(243, 229, 247);
            position: relative;
            background-color: rgb(243, 229, 247);
            box-sizing: border-box;
            padding: 40px;
            box-shadow: rgb(243, 229, 247) 0px 0px 20px 0px;
            overflow: auto;
          "
          aria-label="Feature Survey"
          tabindex="-1"
        >
          <button
            id="pendo-close-guide-pmf"
            class="_pendo-close-guide"
            style="
              color: rgb(243, 229, 247);
              border: 0px;
              z-index: 20;
              position: absolute !important;
              right: 15px;
              top: 6px;
              background-color: rgba(255, 255, 255, 0);
              padding: 0px;
              font-family: Helvetica;
              font-size: 32px;
              font-weight: 100;
              line-height: 1;
            "
            aria-label="Close"
          >
            ×
          </button>
          <form
            id="survey-item-wrapper__pmf"
            name="pmf"
            class="pendo-survey-wrapper"
            data-pendo-poll-id="pmf"
          >
            <div
              id="pendo-text-pmf-q"
              class="bb-text _pendo-text-custom"
              style="
                display: block;
                color: rgb(39, 53, 64);
                margin: 13px 0px 0px;
                line-height: 1.5;
                font-size: 16px;
                font-weight: 400;
                text-align: left;
              "
            >
              <div class="bb-text _pendo-simple-text">
                <h3 class="bb-text _pendo-simple-text">
                  How would you feel if you could no longer use [FEATURE NAME]?<span
                    class="_pendo-required-indicator"
                    style="color: red; font-style: italic"
                    title="Question is required"
                  >
                    *</span
                  >
                </h3>
              </div>
            </div>
            <div
              id="survey-single-choice-answers"
              style="display: block; height: auto; color: rgb(0, 0, 0); font-size: 14px"
            >
              <span style="display: inline-block; font-size: 16px">
                <input
                  id="pmf-c1"
                  name="pmf-choice"
                  type="radio"
                  class="pendo-radio"
                  style="display: inline-block; margin: 6px 0px 0px"
                />
                <label
                  class="pendo-radio"
                  style="display: inline-block; color: rgb(42, 44, 53); font-size: 16px"
                  for="pmf-c1"
                  >Very disappointed</label
                >
              </span>
              <span style="display: inline-block; font-size: 16px">
                <input
                  id="pmf-c2"
                  name="pmf-choice"
                  type="radio"
                  class="pendo-radio"
                  style="display: inline-block; margin: 6px 0px 0px"
                />
                <label
                  class="pendo-radio"
                  style="display: inline-block; color: rgb(42, 44, 53); font-size: 16px"
                  for="pmf-c2"
                  >Mildly disappointed</label
                >
              </span>
              <span style="display: inline-block; font-size: 16px">
                <input
                  id="pmf-c3"
                  name="pmf-choice"
                  type="radio"
                  class="pendo-radio"
                  style="display: inline-block; margin: 6px 0px 0px"
                />
                <label
                  class="pendo-radio"
                  style="display: inline-block; color: rgb(42, 44, 53); font-size: 16px"
                  for="pmf-c3"
                  >Not disappointed</label
                >
              </span>
            </div>
          </form>
          <form
            id="survey-item-wrapper__pmf-text"
            class="pendo-survey-wrapper _pendo-open-text-poll-wrapper"
          >
            <div
              id="pendo-text-pmf-follow"
              class="bb-text _pendo-simple-text"
              style="
                display: block;
                color: rgb(39, 53, 64);
                line-height: 1.5;
                font-size: 16px;
                text-align: left;
              "
            >
              Please share the reasoning behind your rating.
            </div>
            <textarea
              id="survey-open-answer"
              class="_pendo-open-text-poll-input"
              style="
                display: block;
                height: 100px;
                width: 100%;
                color: rgb(42, 44, 53);
                margin: 10px 0px;
                resize: none;
                border-radius: 4px;
                border: 1px solid rgb(218, 220, 229);
                background-color: rgb(255, 255, 255);
                box-sizing: border-box;
                padding: 8px 10px;
                font-size: 14px;
              "
              cols="50"
              rows="4"
            ></textarea>
          </form>
          <div
            id="survey-button-wrapper"
            class="_pendo-row"
            style="display: block; margin: 0px"
            title="Please complete all required questions."
          >
            <button
              id="pendo-button-pmf"
              type="button"
              class="bb-button _pendo-button-custom _pendo-button"
              style="
                display: block;
                width: auto;
                color: rgb(255, 255, 255);
                margin: 10px 0px;
                border-radius: 12px;
                border: 1px solid rgb(29, 53, 79);
                background-color: rgb(29, 53, 79);
                padding: 8px 12px;
                font-size: 14px;
                font-weight: 600;
              "
              aria-label="Next"
            >
              Next
            </button>
          </div>
          <div
            id="pendo-row-pmf-logo"
            class="_pendo-row"
            style="display: block; margin: 0px; padding: 0px"
            data-pendo-display-flex="true"
            data-pendo-justify-content="flex-end"
          >
            <div
              class="pendo-mock-flexbox-row"
              style="display: block; position: relative; width: 100%; min-height: 20px"
            >
              <div
                style="display: inline-block; position: absolute; vertical-align: top; right: 0px"
                class="pendo-mock-flexbox-element"
              >
                <div
                  id="pendo-image-wrapper-pmf"
                  class="pendo-block-wrapper _pendo-image-wrapper"
                >
                  <img
                    id="pendo-image-pmf"
                    class="_pendo-image"
                    style="display: block; height: auto; width: 168px; margin: 0px"
                    src="data:image/svg+xml;utf8,%3Csvg%20xmlns='http://www.w3.org/2000/svg'%20width='168'%20height='32'%3E%3Crect%20width='168'%20height='32'%20fill='%23287A9F'/%3E%3C/svg%3E"
                    alt="Instructure Logo"
                  />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- ── NPS (Product Survey): data-layout="bannerNpsSurvey" ── -->
    <div
      id="pendo-base-nps"
      class="instui-banner-poll _pendo-step-container _pendo-guide-walkthrough_"
      data-layout="bannerNpsSurvey"
      style="visibility: visible"
    >
      <div
        id="pendo-g-nps"
        class="_pendo-step-container-size"
        data-vertical-alignment="Bottom Aligned"
        style="
          bottom: 0px;
          left: 0px;
          right: 0px;
          display: block;
          z-index: 300000;
          pointer-events: all;
          position: fixed;
          visibility: visible;
          height: 205px;
        "
      >
        <div
          id="pendo-guide-container-nps"
          role="complementary"
          class="_pendo-step-container-styles"
          style="
            display: block;
            border: 1px solid rgb(243, 229, 247);
            border-radius: 0px;
            position: relative;
            background-color: rgb(243, 229, 247);
            box-sizing: border-box;
            padding: 40px;
            box-shadow: rgb(243, 229, 247) 0px 0px 20px 0px;
            text-align: center;
          "
          aria-modal="false"
          aria-label="Product Survey"
          tabindex="-1"
        >
          <div
            id="pendo-text-nps-q"
            class="bb-text _pendo-text-subTitle _pendo-nps-poll-question"
            style="
              display: block;
              color: rgb(0, 0, 0);
              font-weight: 700;
              margin: 12px;
              font-size: 22px;
              line-height: 1.2;
              text-align: center;
            "
          >
            <div class="bb-text _pendo-simple-text">
              <h3 class="bb-text _pendo-simple-text">
                How likely are you to recommend Canvas to a friend or colleague?
              </h3>
            </div>
          </div>
